    pass

task.solution:
import pandas as pd

def class_report(names, marks):
    df = pd.DataFrame({"name": names, "marks": marks})
    avg = round(float(df["marks"].mean()), 1)
    top = df[df["marks"] >= 75]["name"].tolist()
    return (avg, top)

