def summary(sales, prices):
    return {}

project.solution:
import math
from collections import Counter

def summary(sales, prices):
    counts = Counter(sales)
    total = math.ceil(sum(prices[s] for s in sales))
    return {"total": total, "top": counts.most_common(1)[0][0], "per_item": dict(counts)}
